#!/bin/bash
set -euo pipefail
WEB=/var/www/fusionpbx/app/agent_dashboard
B64=''
echo "$B64" | base64 -d > /tmp/skykin_config.php
docker cp /tmp/skykin_config.php skykin-web:$WEB/skykin_config.php
docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
$legs=[];
foreach ([5,6,7,8,9] as $i) {
  $legs[]=["direction"=>"inbound","billsec"=>2,"duration"=>5,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+25111619803$i","caller_id_number"=>"+251911528271","start_epoch"=>1700000000+$i,"last_arg"=>"","cc_agent_bridged"=>""];
}
$c=skykin_cdr_collapse_hunt_legs($legs);
echo "short_ivr_hunt=", count($c), " label=", skykin_cdr_result_label($c[0]), "\n";
$rej=[];
foreach ([5,6,7,8] as $i) {
  $rej[]=["direction"=>"inbound","billsec"=>0,"duration"=>1,"hangup_cause"=>"CALL_REJECTED","destination_number"=>"+25111619803$i","caller_id_number"=>"+251911528271","start_epoch"=>1700000100+$i,"last_arg"=>"","cc_agent_bridged"=>""];
}
$c2=skykin_cdr_collapse_hunt_legs($rej);
echo "blacklist_hunt=", count($c2), " label=", skykin_cdr_result_label($c2[0]), "\n";
$ok=["direction"=>"inbound","billsec"=>90,"duration"=>100,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198037","caller_id_number"=>"+251911000001","start_epoch"=>1700000200,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"/203@ahununu"];
$noise=["direction"=>"inbound","billsec"=>2,"duration"=>5,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198038","caller_id_number"=>"+251911000001","start_epoch"=>1700000202,"last_arg"=>"","cc_agent_bridged"=>""];
$c3=skykin_cdr_collapse_hunt_legs([$ok,$noise]);
echo "answered_plus_noise=", count($c3), " label=", skykin_cdr_result_label($c3[0]), "\n";
'
echo DONE
